import pytest

def test_code_first_openapi_spec(code_first_client):
    """Verify that OpenAPI 3.0 specification is auto-generated by flask-smorest (Slide 10-11)."""
    res = code_first_client.get("/openapi.json")
    assert res.status_code == 200
    spec = res.json
    assert spec["openapi"] == "3.0.3"
    assert "/api/v1/products" in spec["paths"]
    assert "/api/v1/products/{id}" in spec["paths"]
    assert "/api/v1/products/{id}/reserve" in spec["paths"]
    assert "/api/v1/orders" in spec["paths"]

def test_code_first_healthz_and_ready(code_first_client):
    """Verify separate /healthz (liveness) and /ready (readiness) endpoints (Slide 36-37)."""
    # Liveness
    res_liveness = code_first_client.get("/healthz")
    assert res_liveness.status_code == 200
    assert res_liveness.json == {"status": "ok"}

    # Readiness
    res_readiness = code_first_client.get("/ready")
    assert res_readiness.status_code == 200
    assert res_readiness.json["status"] == "ok"
    assert res_readiness.json["checks"]["db"] == "ok"

def test_product_crud_lifecycle(code_first_client):
    """Verify full CRUD lifecycle across the 6 required endpoints (Slide 24, 27-28)."""
    # 1. POST create product
    payload = {
        "sku": "SKU-IPHONE-15",
        "name": "Apple iPhone 15 Pro",
        "description": "256GB Natural Titanium",
        "price_cents": 120000,
        "qty_in_stock": 10
    }
    res_create = code_first_client.post("/api/v1/products", json=payload)
    assert res_create.status_code == 201
    prod = res_create.json
    prod_id = prod["id"]
    assert prod["sku"] == "SKU-IPHONE-15"
    assert prod["qty_in_stock"] == 10
    assert prod["archived"] is False

    # 2. Duplicate SKU returns 409 Conflict
    res_dup = code_first_client.post("/api/v1/products", json=payload)
    assert res_dup.status_code == 409
    assert res_dup.json["code"] == "conflict"

    # 3. GET product by ID
    res_get = code_first_client.get(f"/api/v1/products/{prod_id}")
    assert res_get.status_code == 200
    assert res_get.json["name"] == "Apple iPhone 15 Pro"

    # 4. POST reserve stock
    res_res = code_first_client.post(f"/api/v1/products/{prod_id}/reserve", json={"qty": 3})
    assert res_res.status_code == 200
    assert res_res.json["qty_in_stock"] == 7

    # Reserve exceeding stock returns 409 OutOfStock
    res_res_fail = code_first_client.post(f"/api/v1/products/{prod_id}/reserve", json={"qty": 8})
    assert res_res_fail.status_code == 409
    assert res_res_fail.json["code"] == "out_of_stock"

    # 5. PATCH partial update
    res_patch = code_first_client.patch(f"/api/v1/products/{prod_id}", json={
        "name": "Apple iPhone 15 Pro Max",
        "price_cents": 135000
    })
    assert res_patch.status_code == 200
    assert res_patch.json["name"] == "Apple iPhone 15 Pro Max"
    assert res_patch.json["price_cents"] == 135000

    # 6. GET list with pagination
    res_list = code_first_client.get("/api/v1/products?page=1&size=10")
    assert res_list.status_code == 200
    assert res_list.json["page"] == 1
    assert res_list.json["size"] == 10
    assert res_list.json["total"] == 1
    assert len(res_list.json["items"]) == 1

    # 7. DELETE soft-delete (archived=True)
    res_del = code_first_client.delete(f"/api/v1/products/{prod_id}")
    assert res_del.status_code == 204

    # Verification: Archived product must be excluded from list and get
    res_get_archived = code_first_client.get(f"/api/v1/products/{prod_id}")
    assert res_get_archived.status_code == 404

    res_list_after = code_first_client.get("/api/v1/products")
    assert res_list_after.json["total"] == 0
    assert len(res_list_after.json["items"]) == 0

def test_product_validation(code_first_client):
    """Verify input validation rules (Slide 26, 32)."""
    # Negative price
    res1 = code_first_client.post("/api/v1/products", json={
        "sku": "SKU-BAD-01",
        "name": "Bad Product",
        "price_cents": -500
    })
    assert res1.status_code == 422

    # Empty name
    res2 = code_first_client.post("/api/v1/products", json={
        "sku": "SKU-BAD-02",
        "name": "   ",
        "price_cents": 1000
    })
    assert res2.status_code == 422

